body.css:
/* Program sheets reach descendants of a surface region, never Tern's chrome. */
[data-role='canvas'], [data-role='composer'], [data-role='composer-footer'],
[data-role='status'], [data-role='activity'] {
  --hft-gold: light-dark(#805c20, #d5b475);
  --hft-ink: light-dark(#292722, #ece8df);
  --hft-muted: light-dark(#686359, #aaa397);
  --hft-line: light-dark(#ded8cc, #3a3833);
  --hft-panel: light-dark(#f5f2ec, #242422);
  --hft-soft: light-dark(#ebe6db, #30302c);
  --sf-accent: var(--hft-gold);
  --sf-c-accent: var(--hft-gold);
}

[data-role='canvas'] { padding: 20px 28px 24px; color: var(--hft-ink); }
[data-role='composer'], [data-role='composer-footer'], [data-role='status'], [data-role='activity'] { margin-left: 24px; margin-right: 24px; }
[data-role='status'] { margin-bottom: 12px; }
[data-role='welcome'] {
  padding: 32px 4px 28px;
  animation: hft-arrive 480ms ease-out both;
}
.hft-wordmark { font: inherit; font-family: var(--sans, system-ui); font-size: 38px;
  font-weight: 650; letter-spacing: -1.5px; line-height: 1.15; margin: 0; }
.hft-eyebrow { font-family: var(--sans, system-ui); font-size: 10px; font-weight: 600;
  letter-spacing: 2px; color: var(--hft-muted); }
.hft-tagline { font-family: var(--sans, system-ui); font-size: 17px; line-height: 1.6;
  color: var(--hft-muted); margin: 0; }
[data-role='welcome-brand'] { gap: 22px; align-items: center; }
[data-role='welcome-logo'] .sf-img-svg { overflow: visible; }
.hft-logo-path, .hft-wing { fill: light-dark(#805c20, #d5b475); }
.hft-context { display: flex; flex-wrap: wrap; gap: 8px 22px; font-family: var(--sans, system-ui);
  font-size: 11px; color: var(--hft-muted); }
.hft-context-label { font-weight: 600; color: var(--hft-gold); margin-right: 6px; }
.hft-actions { display: flex; flex-direction: row; flex-wrap: wrap; gap: 8px; }
.hft-button { font-family: var(--sans, system-ui); font-size: 12px; font-weight: 500;
  padding: 9px 14px; border-radius: 9px; background: var(--hft-panel);
  color: var(--hft-ink); border: 1px solid var(--hft-line); cursor: pointer;
  transition: background 140ms ease, border-color 140ms ease; }
.hft-button:hover { background: var(--hft-soft); border-color: var(--hft-gold); }
.hft-button:active { background: var(--hft-soft); }
.hft-primary { background: light-dark(#805c20, #d5b475);
  border-color: light-dark(#805c20, #d5b475); color: light-dark(#ffffff, #242017); }
.hft-primary:hover { background: light-dark(#6f4d17, #e2c48e); }
.hft-button.hft-disabled { opacity: 0.45; cursor: default; }
.sf.sf-card[data-role='message-user'] { background: var(--hft-panel); border: 1px solid var(--hft-line);
  border-radius: 12px; padding: 12px 16px; }
.sf.sf-card[data-role='message-user'] .sf-card-head { font-family: var(--sans, system-ui); font-size: 10px;
  font-weight: 600; color: var(--hft-muted); margin-bottom: 6px; }
.sf.sf-card[data-role='message-user'] .sf-text { line-height: 1.65; }
.sf.sf-card[data-role='message-assistant'] { padding: 6px 4px 12px; }
.sf.sf-card[data-role='message-assistant'] .sf-card-head { font-family: var(--sans, system-ui); font-size: 11px;
  font-weight: 600; color: var(--hft-gold); margin-bottom: 10px; }
.sf.sf-card[data-role='message-assistant'] .sf-md { line-height: 1.75; }
.sf.sf-tool[data-role='tool'] { border: 1px solid var(--hft-line); border-radius: 10px;
  background: var(--hft-panel); }
.sf.sf-tool[data-role='tool'] .sf-code { font-size: 12px; line-height: 1.6; }
.sf.sf-card[data-role='approval'], .sf.sf-card[data-role='clarification'] {
  border: 1px solid var(--hft-gold); border-radius: 12px;
  background: var(--hft-panel); padding: 16px; }
[data-role='notice'] { font-family: var(--sans, system-ui); font-size: 12px; color: var(--hft-muted); }
.sf.sf-card[data-role='error'] { border-left: 2px solid var(--sf-bad); padding: 10px 14px; }
[data-role='activity'] { min-height: 30px; align-items: center; }
.hft-activity-label { font-family: var(--sans, system-ui); font-size: 12px; color: var(--hft-muted); }
.hft-orbit { position: relative; width: 28px; height: 28px; flex-shrink: 0; }
.hft-orbit .sf-image { position: absolute; inset: 4px; }
.hft-orbit-ring { position: absolute; inset: 0; border: 1.5px solid var(--hft-line);
  border-top-color: var(--hft-gold); border-right-color: var(--hft-gold); border-radius: 50%;
  animation: hft-orbit 1600ms linear infinite; }
.hft-orbit .hft-wing { animation: hft-breathe 1600ms ease-in-out infinite; }
[data-role='composer'] { border: 1px solid var(--hft-line); border-radius: 12px;
  background: var(--hft-panel); padding: 14px 16px; }
[data-role='composer'].focused { border-color: var(--hft-gold);
  box-shadow: 0 0 0 2px light-dark(#805c2014, #d5b47514); }
[data-role='composer'] .sf-ed-ph { color: var(--hft-muted); }
[data-role='composer'] .sf-ed-prompt { color: var(--hft-gold); }
[data-role='composer-footer'] { display: flex; flex-wrap: wrap; align-items: center;
  justify-content: space-between; gap: 8px; padding: 0 2px; }
.hft-hints { font-family: var(--sans, system-ui); font-size: 10px; color: var(--hft-muted); }
[data-role='status'] { color: var(--hft-muted); font-size: 10px; }
@keyframes hft-arrive { from { opacity: 0; transform: translateY(6px); }
  to { opacity: 1; transform: translateY(0); } }
@keyframes hft-orbit { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
@keyframes hft-breathe { 0%, 100% { opacity: 0.7; } 50% { opacity: 1; } }
.sf-paused .hft-orbit-ring, .sf-paused .hft-wing,
.sf-covered .hft-orbit-ring, .sf-covered .hft-wing,
.sf-paused [data-role='welcome'], .sf-covered [data-role='welcome'] {
  animation-play-state: paused; }
.sf-still .hft-orbit-ring, .sf-still .hft-wing,
.sf-still [data-role='welcome'] { animation: none; }
@media (prefers-reduced-motion: reduce) {
  .hft-orbit-ring, .hft-wing, [data-role='welcome'] { animation: none; }
  .hft-button { transition: none; }
}
@media (prefers-contrast: more) {
  [data-role='canvas'], [data-role='composer'], [data-role='composer-footer'],
  [data-role='status'], [data-role='activity'] { --hft-ink: var(--t1);
    --hft-muted: var(--t2); --hft-line: var(--l3); }
}
@media (max-width: 600px) {
  [data-role='canvas'] { padding: 12px 14px 18px; }
  [data-role='composer'], [data-role='composer-footer'], [data-role='status'], [data-role='activity'] { margin-left: 12px; margin-right: 12px; }
  [data-role='welcome'] { padding-top: 20px; }
  .hft-wordmark { font-size: 30px; }
  .hft-tagline { font-size: 14px; }
  .hft-hints { font-size: 9px; }
}
.hft-activity-content { display: flex; align-items: center; gap: 10px; }
.hft-still-mark { width: 28px; display: flex; justify-content: center; }

.hft-button.hft-disabled:hover { background: var(--hft-gold); border-color: var(--hft-gold); }

.sf.sf-card[data-role='message-user'] .sf-card-head,
.sf.sf-card[data-role='message-assistant'] .sf-card-head { padding: 0; }
.sf.sf-card[data-role='message-user'] .sf-card-body,
.sf.sf-card[data-role='message-assistant'] .sf-card-body { padding: 0; }
.sf.sf-tool[data-role='tool'] { padding: 10px 12px; overflow: hidden; }
/* Explicit UI face; the terminal's face remains on editors, prose, code and paths. */
.sf.sf-el { font-family: 'Geist', 'SF Pro Text', system-ui, sans-serif; }
